// Transform Snowflake predictions for Supabase
const predictions = $input.all();
const transformed = [];

for (const pred of predictions) {
  const item = pred.json;
  transformed.push({
    customer_id: item.CUSTOMER_ID,
    predicted_ltv: parseFloat(item.LIFETIME_VALUE_PREDICTION || 0),
    churn_risk: parseFloat(item.CHURN_RISK_SCORE || 0),
    upsell_likelihood: parseFloat(item.UPSELL_LIKELIHOOD_SCORE || 0),
    updated_at: new Date().toISOString()
  });
}

return transformed;

